# WAR ARENA - Production Composition Root (live GMGN wiring) - Installer
# Assembles GmgnCliExecutor -> scan/monitor -> ArenaSession into one runtime.
# Run from project root:  powershell -ExecutionPolicy Bypass -File .\install-runtime.ps1
$ErrorActionPreference = "Stop"
Write-Host "WAR - Production composition root installer" -ForegroundColor Cyan
function Write-B64([string]$Path,[string]$B64){
  $dir = Split-Path -Parent $Path
  if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
  [System.IO.File]::WriteAllBytes($Path,[System.Convert]::FromBase64String($B64))
  Write-Host "  wrote $Path" -ForegroundColor DarkGray
}

Write-B64 "src/integration/warRuntime.ts" ""
Write-B64 "tests/unit/warRuntime.test.ts" ""

# Ensure warRuntime is exported (idempotent)
$bar = "src/integration/index.ts"
if (Test-Path $bar) {
  $c = Get-Content $bar -Raw
  if ($c -notmatch "warRuntime") {
    $enc = New-Object System.Text.UTF8Encoding($false)
    $line = 'export * from "./warRuntime.js";'
    $c = $c.TrimEnd() + [Environment]::NewLine + $line + [Environment]::NewLine
    [System.IO.File]::WriteAllText((Join-Path (Get-Location) $bar), $c, $enc)
    Write-Host "  patched integration/index.ts export" -ForegroundColor DarkGray
  } else { Write-Host "  already exports warRuntime" -ForegroundColor DarkGray }
}

Write-Host ""; Write-Host "Verifying gate ..." -ForegroundColor Cyan
npx tsc --noEmit; if ($LASTEXITCODE -ne 0){ throw "typecheck failed" }
npx vitest run
Write-Host ""; Write-Host "Composition root installed. Expected: 873 passed + 1 skipped, 413 guards." -ForegroundColor Green
